"""Tests for tasks_api.models — enums, Tag normalisation, Task.is_overdue."""

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── TaskStatus ──────────────────────────────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str_enum(self):
        assert isinstance(TaskStatus.PENDING, str)
        assert str(TaskStatus.DONE) == "done"


# ── TaskPriority ────────────────────────────────────────────────────────

class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_is_smallest(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0

    def test_order_key_medium(self):
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1

    def test_order_key_low_is_largest(self):
        assert TaskPriority.order_key(TaskPriority.LOW) == 2

    def test_order_key_ordering(self):
        keys = [TaskPriority.order_key(p) for p in TaskPriority]
        # LOW(2) > MEDIUM(1) > HIGH(0)
        assert keys == [2, 1, 0]  # iteration order: LOW, MEDIUM, HIGH


# ── Tag ─────────────────────────────────────────────────────────────────

class TestTag:
    def test_normalises_to_lowercase(self):
        assert Tag("Foo").name == "foo"

    def test_strips_whitespace(self):
        assert Tag("  bar  ").name == "bar"

    def test_strips_and_lowercases(self):
        assert Tag("  Hello  ").name == "hello"

    @pytest.mark.parametrize("valid", ["abc", "a-b", "a_b", "abc123", "x", "a" * 32])
    def test_valid_names(self, valid):
        assert Tag(valid).name == valid.strip().lower()

    def test_empty_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    @pytest.mark.parametrize("bad", ["hello world", "a@b", "a.b", "a!b", "a/b"])
    def test_illegal_characters_raise(self, bad):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad)

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]


# ── Task.is_overdue ────────────────────────────────────────────────────

class TestTaskIsOverdue:
    NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)

    def test_overdue_when_due_in_past_and_pending(self):
        task = Task(id=1, title="t", due_at=self.NOW - timedelta(hours=1))
        assert task.is_overdue(self.NOW) is True

    def test_not_overdue_when_done(self):
        task = Task(
            id=1, title="t",
            status=TaskStatus.DONE,
            due_at=self.NOW - timedelta(hours=1),
        )
        assert task.is_overdue(self.NOW) is False

    def test_not_overdue_when_no_due_at(self):
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(self.NOW) is False

    def test_not_overdue_when_due_in_future(self):
        task = Task(id=1, title="t", due_at=self.NOW + timedelta(hours=1))
        assert task.is_overdue(self.NOW) is False

    def test_not_overdue_when_due_at_equals_now(self):
        # due_at < now is False when equal
        task = Task(id=1, title="t", due_at=self.NOW)
        assert task.is_overdue(self.NOW) is False

"""Tests for tasks_api.repository — InMemoryTaskRepository + normalize_tags."""

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


# ── InMemoryTaskRepository ──────────────────────────────────────────────

class TestInMemoryTaskRepository:
    @pytest.fixture()
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, task_id: int, title: str = "t") -> Task:
        return Task(id=task_id, title=title)

    # next_id
    def test_next_id_starts_at_one(self, repo):
        assert repo.next_id() == 1

    def test_next_id_increments(self, repo):
        first = repo.next_id()
        second = repo.next_id()
        assert second == first + 1

    # add / get
    def test_add_and_get(self, repo):
        task = self._make_task(1)
        repo.add(task)
        fetched = repo.get(1)
        assert fetched is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1))

    # list
    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_returns_all(self, repo):
        repo.add(self._make_task(1, "a"))
        repo.add(self._make_task(2, "b"))
        ids = {t.id for t in repo.list()}
        assert ids == {1, 2}

    # update
    def test_update_existing(self, repo):
        task = self._make_task(1, "old")
        repo.add(task)
        task.title = "new"
        repo.update(task)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(99))

    # delete
    def test_delete_existing_returns_true(self, repo):
        repo.add(self._make_task(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


