class TestNormalizeTags:
    def test_converts_strings_to_tags(self):
        result = normalize_tags(["foo", "bar"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["foo", "bar"]

    def test_deduplicates_preserving_first_seen(self):
        result = normalize_tags(["Foo", "foo", "FOO", "bar"])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_accepts_tag_objects(self):
        result = normalize_tags([Tag("x"), Tag("y")])
        assert [t.name for t in result] == ["x", "y"]

    def test_mixed_strings_and_tags(self):
        result = normalize_tags(["alpha", Tag("beta"), "Alpha"])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

